description:
Implement a `useHover` hook that returns a `[ref, isHovered]` tuple. Attach the ref to any element and `isHovered` will be `true` while the pointer is over the element.

**Example:**
```tsx
const [ref, isHovered] = useHover();
return <div ref={ref}>{isHovered ? 'Hovering!' : 'Hover me'}</div>;
```

starter_code:
import { useEffect, useRef, useState } from 'react';

export function useHover<T extends Element>(): [React.RefObject<T>, boolean] {
  // your code here
}

test_suite:
test('isHovered is false initially', () => {
  const { result } = renderHook(() => useHover());
  expect(result.current[1]).toBe(false);
});

test('isHovered is true after mouseenter', () => {
  const { result } = renderHook(() => useHover());
  const div = document.createElement('div');
  result.current[0].current = div;
  act(() => div.dispatchEvent(new MouseEvent('mouseenter')));
  expect(result.current[1]).toBe(true);
});

test('isHovered is false after mouseleave', () => {
  const { result } = renderHook(() => useHover());
  const div = document.createElement('div');
  result.current[0].current = div;
  act(() => div.dispatchEvent(new MouseEvent('mouseenter')));
  act(() => div.dispatchEvent(new MouseEvent('mouseleave')));
  expect(result.current[1]).toBe(false);
});

// __hidden__
test('ref is a RefObject', () => {
  const { result } = renderHook(() => useHover());
  expect(result.current[0]).toHaveProperty('current');
});

solution:
import { useEffect, useRef, useState } from 'react';

export function useHover<T extends Element>(): [React.RefObject<T>, boolean] {
  const ref = useRef<T>(null);
  const [isHovered, setIsHovered] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const enter = () => setIsHovered(true);
    const leave = () => setIsHovered(false);
    el.addEventListener('mouseenter', enter);
    el.addEventListener('mouseleave', leave);
    return () => {
      el.removeEventListener('mouseenter', enter);
      el.removeEventListener('mouseleave', leave);
    };
  }, []);

  return [ref, isHovered];
}
